export class SessionRefreshCoordinator {
  private inflight?: Promise<string>;

  refresh(fetchToken: () => Promise<string>): Promise<string> {
    this.inflight ??= fetchToken().finally(() => { this.inflight = undefined; });
    return this.inflight;
  }
}
